-- Configuración autónoma por sucursal, sin sustituir los menús existentes.
alter table gestlok_chat_private.wai_carta_paginas add column if not exists activa boolean not null default true;
alter table gestlok_chat_private.wai_carta_paginas add column if not exists editada_at timestamptz not null default now();

create or replace function public.gestlok_chat_wai_carta_editor(p_sucursal uuid,p_cambio jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare anterior gestlok_chat_private.wai_carta_paginas%rowtype; k text; titulo_n text; foto text; orden_n int;
 cats text[]; prods text[]; detalle text; grupo text; activo boolean;
begin
 if auth.uid() is null or coalesce(gestlok_chat_private.wai_portal_nivel(p_sucursal),'') not in ('gestionar','configurar') then raise exception 'Sin permiso' using errcode='42501';end if;
 if p_cambio is not null then
  -- Serialize saves for the same local, never for unrelated shops.
  perform 1 from gestlok_chat_private.sucursales where id=p_sucursal for update;
  if jsonb_typeof(p_cambio) is distinct from 'object' or jsonb_typeof(p_cambio->'titulo') is distinct from 'string'
   or jsonb_typeof(p_cambio->'imagen_url') is distinct from 'string' or jsonb_typeof(p_cambio->'activa') is distinct from 'boolean'
   or jsonb_typeof(p_cambio->'categorias') is distinct from 'array' or jsonb_typeof(p_cambio->'productos_nombres') is distinct from 'array'
   or coalesce(p_cambio->>'orden','') !~ '^[0-9]{1,4}$' then raise exception 'Configuración inválida';end if;
  k=nullif(p_cambio->>'clave',''); titulo_n=btrim(p_cambio->>'titulo'); foto=btrim(p_cambio->>'imagen_url'); orden_n=(p_cambio->>'orden')::int; activo=(p_cambio->>'activa')::boolean;
  if k is not null then
   select * into anterior from gestlok_chat_private.wai_carta_paginas where sucursal_id=p_sucursal and clave=k;
   if not found or anterior.editada_at::text is distinct from p_cambio->>'version' then raise exception 'La opción cambió. Actualizá el editor antes de guardar.';end if;
  else
   if (select count(*) from gestlok_chat_private.wai_carta_paginas where sucursal_id=p_sucursal)>=60 then raise exception 'Máximo 60 opciones por local (incluidas archivadas)';end if;
   k='p_'||replace(gen_random_uuid()::text,'-','');
  end if;
  if length(titulo_n) not between 1 and 60 or length(foto)>1500 then raise exception 'Revisá el nombre o la foto';end if;
  if foto<>'' and not gestlok_chat_private.wai_imagen_permitida(p_sucursal,foto) and foto is distinct from anterior.imagen_url then raise exception 'Subí una imagen autorizada de este local';end if;
  -- New URLs are generated by Storage for THIS local. Legacy reviewed sheets remain intact.
  if foto<>'' and foto is distinct from anterior.imagen_url and foto not like '%/storage/v1/object/public/gestlok-chat-cartas/'||p_sucursal::text||'/%' then raise exception 'Subí la foto desde este editor';end if;
  if exists(select 1 from jsonb_array_elements(p_cambio->'categorias') x where jsonb_typeof(x)<>'string') or exists(select 1 from jsonb_array_elements(p_cambio->'productos_nombres') x where jsonb_typeof(x)<>'string') then raise exception 'Asociaciones inválidas';end if;
  select coalesce(array_agg(distinct x order by x),'{}') into cats from jsonb_array_elements_text(p_cambio->'categorias') x;
  select coalesce(array_agg(distinct x order by x),'{}') into prods from jsonb_array_elements_text(p_cambio->'productos_nombres') x;
  if cardinality(cats)>100 or cardinality(prods)>500 then raise exception 'Demasiadas asociaciones';end if;
  if exists(select 1 from unnest(cats) x where not exists(select 1 from gestlok_chat_private.categorias c where c.sucursal_id=p_sucursal and c.nombre=x) and not (x=any(coalesce(anterior.categorias,'{}')))) then raise exception 'Categoría ajena al local';end if;
  if exists(select 1 from unnest(prods) x where not exists(select 1 from gestlok_chat_private.productos p join gestlok_chat_private.categorias c on c.id=p.categoria_id where p.sucursal_id=p_sucursal and c.sucursal_id=p_sucursal and p.nombre=x and c.nombre=any(cats)) and not (x=any(coalesce(anterior.productos_nombres,'{}')))) then raise exception 'Producto ajeno a las categorías del local';end if;
  detalle=nullif(p_cambio->>'detalle_clave','');grupo=nullif(btrim(p_cambio->>'detalle_grupo'),'');
  if (detalle is null)<>(grupo is null) or (grupo is not null and length(grupo)>120) or (detalle is not null and (detalle=k or not exists(select 1 from gestlok_chat_private.wai_carta_paginas w where w.sucursal_id=p_sucursal and w.clave=detalle))) then raise exception 'Revisá la foto de detalle y el grupo de opciones';end if;
  if activo and not coalesce(gestlok_chat_private.wai_imagen_permitida(p_sucursal,foto),false) then raise exception 'Una opción visual activa necesita una foto autorizada';end if;
  if activo and not coalesce(anterior.activa,false) and (select count(*) from gestlok_chat_private.wai_carta_paginas w where w.sucursal_id=p_sucursal and w.activa)>=6 then raise exception 'Máximo 6 botones visuales activos; archivá uno para habilitar otro';end if;
  if activo and exists(select 1 from gestlok_chat_private.wai_carta_paginas w where w.sucursal_id=p_sucursal and w.clave<>k and w.activa and lower(w.titulo)=lower(titulo_n)) then raise exception 'Ya existe una opción activa con ese nombre';end if;
  insert into gestlok_chat_private.wai_carta_paginas(sucursal_id,clave,titulo,imagen_url,orden,categorias,productos_nombres,detalle_clave,detalle_grupo,activa,editada_at)
  values(p_sucursal,k,titulo_n,foto,orden_n,cats,prods,detalle,grupo,activo,clock_timestamp())
  on conflict(sucursal_id,clave) do update set titulo=excluded.titulo,imagen_url=excluded.imagen_url,orden=excluded.orden,categorias=excluded.categorias,productos_nombres=excluded.productos_nombres,detalle_clave=excluded.detalle_clave,detalle_grupo=excluded.detalle_grupo,activa=excluded.activa,editada_at=excluded.editada_at;
 end if;
 return jsonb_build_object(
  'paginas',coalesce((select jsonb_agg(to_jsonb(w)-'sucursal_id'-'editada_at'||jsonb_build_object('version',w.editada_at::text) order by w.orden,w.clave) from gestlok_chat_private.wai_carta_paginas w where w.sucursal_id=p_sucursal),'[]'),
  'categorias',coalesce((select jsonb_agg(jsonb_build_object('nombre',c.nombre,'activa',c.activa) order by c.orden,c.nombre) from gestlok_chat_private.categorias c where c.sucursal_id=p_sucursal),'[]'),
  'productos',coalesce((select jsonb_agg(jsonb_build_object('nombre',p.nombre,'categoria',c.nombre) order by p.orden,p.nombre) from gestlok_chat_private.productos p join gestlok_chat_private.categorias c on c.id=p.categoria_id where p.sucursal_id=p_sucursal and c.sucursal_id=p_sucursal),'[]'));
end$$;
revoke all on function public.gestlok_chat_wai_carta_editor(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.gestlok_chat_wai_carta_editor(uuid,jsonb) to authenticated;

-- Existing functions remain intact except for the visibility check.
-- Templates inherit active flags rather than silently restoring archived pages.
do $migration$
declare sig text; old text; new text; def text;
begin
 for sig,old,new in select * from (values
 ('gestlok_chat_private.wai_menu_paginas(uuid)','where p.sucursal_id=p_sucursal and gestlok_chat_private.wai_imagen_permitida','where p.sucursal_id=p_sucursal and p.activa and gestlok_chat_private.wai_imagen_permitida'),
 ('gestlok_chat_private.wai_ofertas(uuid,text,text)','where w.sucursal_id=s and ''carta_''||w.clave=carta','where w.sucursal_id=s and w.activa and ''carta_''||w.clave=carta'),
 ('gestlok_chat_private.wai_aplicar_plantilla_nueva()','detalle_grupo,productos_nombres)'||chr(10)||' select new.id,p.clave,p.titulo,p.imagen_url,p.orden,p.categorias,p.detalle_clave,p.detalle_grupo,p.productos_nombres','detalle_grupo,productos_nombres,activa)'||chr(10)||' select new.id,p.clave,p.titulo,p.imagen_url,p.orden,p.categorias,p.detalle_clave,p.detalle_grupo,p.productos_nombres,coalesce(p.activa,true)')
 ) x(sig,old,new) loop
  def=pg_get_functiondef(sig::regprocedure);
  if strpos(def,new)>0 then continue;end if;
  if (length(def)-length(replace(def,old,'')))/length(old)<>1 then raise exception 'Revisar versión de %',sig;end if;
  execute replace(def,old,new);
 end loop;
end $migration$;
-- Generic options (any industry): snapshot the optional photo with the response.
create or replace function gestlok_chat_private.wai_encolar_respuesta_configurada(p gestlok_chat_private.wai_pilotos,e text,o jsonb)
returns boolean language plpgsql set search_path='' as $$
declare u text:=o->>'imagen_url'; texto text:=o->>'respuesta'; apto boolean;
begin
 if not gestlok_chat_private.wai_imagen_permitida(p.sucursal_id,u) then u=null;end if;
 apto=u is not null and exists(select 1 from gestlok_chat_private.wai_sesiones w where w.habilitacion_id=p.habilitacion_id and w.imagenes_at>now()-interval '30 seconds' and w.imagenes_at>=w.solicitada_at);
 if not gestlok_chat_private.wai_pedido_encolar(p.id,e,case when u is not null and not apto then texto||chr(10)||u else texto end) then return false;end if;
 if apto and gestlok_chat_private.wai_pedido_encolar(p.id,e||':foto','Imagen de referencia') then
  update gestlok_chat_private.wai_mensajes set imagen_url=u where piloto_id=p.id and evento=e||':foto' and direccion='salida' and estado='pendiente' and imagen_url is null;
 end if;
 return true;
end$$;
revoke all on function gestlok_chat_private.wai_encolar_respuesta_configurada(gestlok_chat_private.wai_pilotos,text,jsonb) from public,anon,authenticated;
